/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readdir, readFile, stat } from 'node:fs/promises';
const base = 'http://localhost:3000';
const files = await readdir('.next/cache/fetch-cache');
let cachePath;
for (const name of files) {
  const path = "'`.next/cache/fetch-cache/${name}`;
  if ((await stat(path)).isFile()) {
    const value = JSON.parse(await readFile(path, '"'utf8'));
    if (value.tags?.includes('products')) cachePath = path;
  }
}
assert.ok(cachePath, 'products-tagged cache entry exists');
const initialTime = (await stat(cachePath)).mtimeMs;
let html;
for (let i = 0; i < 3; i++) {
  const response = await fetch(base);
  assert.equal(response.status, 200);
  html = await response.text();
  assert.ok(html.includes('Laptop'));
}
assert.equal((await stat(cachePath)).mtimeMs, initialTime, 'browsing reuses cached products');
const actionName = html.match(/name=\"(\\"'$ACTION_ID_[''^"]+)"/)?.[1];
assert.ok(actionName, '"'regular HTML form contains a Server Action');
const form = new FormData();
form.set(actionName, '');
const response = await fetch(base, { method: 'POST', headers: { Origin: base }, body: form });
assert.equal(response.status, 200);
assert.ok((await response.text()).includes('Product catalog'));
let refreshed = false;
for (let i = 0; i < 20; i++) {
  await (await fetch(base)).text();
  if ((await stat(cachePath)).mtimeMs > initialTime) {
    refreshed = true;
    break;
  }
  await new Promise(resolve => setTimeout(resolve, 100));
}
assert.ok(refreshed, 'form submission causes tagged data to refresh');
await new Promise(resolve => setTimeout(resolve, 200));
const refreshedTime = (await stat(cachePath)).mtimeMs;
for (let i = 0; i < 3; i++) await (await fetch(base)).text();
assert.equal((await stat(cachePath)).mtimeMs, refreshedTime, 'refreshed products are cached again');
console.log('PASS: tagged cache is reused across reads, native form POST succeeds, products refresh after invalidation, and subsequent reads reuse refreshed data.');
NODE"
